if(this.VenworksCUIRuntimeInstance == null || this.VenworksCUIRuntimeInstance.isDisposed)
{
   try
   {
      this.VenworksCUIRuntimeInstance = new CUIRuntime(this);
      this.VenworksCUIRuntimeInstance.load();
      if(this.VenworksCUIBootstrapDiagnostics != null &&
         this.VenworksCUIBootstrapDiagnostics.parent === this)
      {
         this.removeChild(this.VenworksCUIBootstrapDiagnostics);
      }
      this.VenworksCUIBootstrapDiagnostics = null;
   }
   catch(venworksBootstrapError:Error)
   {
      this.VenworksCUIRuntimeInstance = null;
      try
      {
         if(this.VenworksCUIBootstrapDiagnostics == null)
         {
            this.VenworksCUIBootstrapDiagnostics = new CUIDiagnosticsPanel();
            this.addChild(this.VenworksCUIBootstrapDiagnostics);
         }
         this.VenworksCUIBootstrapDiagnostics.showError(
            "CUI STARTUP ERROR",
            "CODE: CUI-EVT-BOOTSTRAP\n" + venworksBootstrapError.toString()
         );
      }
      catch(venworksDiagnosticsError:Error)
      {
         trace("CUI-EVT-BOOTSTRAP | " + venworksBootstrapError.toString());
      }
   }
}
